type Customer interface{ Balance() int }
type CustomerRole struct{ core *CustomerCore }               // base role + forwarder
func (r *CustomerRole) Balance() int { return r.core.Balance() }
type BorrowerRole struct{ CustomerRole; Limit int }          // promoted Balance plus role state

type CustomerCore struct {
    mu    sync.Mutex
    roles map[reflect.Type]any
}
func (c *CustomerCore) AddRole(role any) { c.mu.Lock(); defer c.mu.Unlock(); c.roles[reflect.TypeOf(role)] = role }
func (c *CustomerCore) GetRole(t reflect.Type) (any, bool) { c.mu.Lock(); defer c.mu.Unlock(); r, ok := c.roles[t]; return r, ok }
